 TB(['Faixa','Situação','Cliente','Nº','Qtd reparos','UF / Unidade','Tipos de reparo','Aberturas','Abertas'],g.slice(0,300).map(v=>{const s=st(v);return[v.length>=4?'<span class="bd">4+</span>':v.length==3?'<span class="wa">3</span>':v.length,s=='r'?'<span class="irrp">IRR2+</span>':'<span class="irrg">✔ Finalizado</span>',E(v[0].nome),v[0].cli,v.length,v[0].uf+' / '+E(v[0].proj),E([...new Set(v.map(o=>o.tipo))].join(' | ')),v.map(o=>fd(o.ab).slice(0,5)).sort().join(', '),ab(v)]}));
 $('#mm').onchange=e=>{MM=+e.target.value;mx()}}
const GAR={'Instalação':30,'Mudança':30};let GO='',GT='';
function gar(V,D){const el=$('#s9');if(!R.some(o=>o.cli)){el.innerHTML='<p class="mu">Reenvie o Excel pelo botão de atualizar base.</p>';return}
 const fin=o=>(o.cat=='Instalação'||o.cat=='Mudança')&&o.closed&&!o.st.includes('Improd'),src=R.filter(o=>fin(o)&&o.fim&&o.cli),ix=GR(src,o=>o.cli),G=[];
 Object.values(ix).forEach(a=>a.sort((x,y)=>x.fim-y.fim));
 V.filter(o=>o.cat=='Reparo'&&o.cli&&o.ab).forEach(r=>{const a=ix[r.cli];if(!a)return;let s=null;for(const x of a){if(x.fim<=r.ab)s=x;else break}if(!s)return;const d=(r.ab-s.fim)/864e5;if(d<=GAR[s.cat])G.push({r,s,d:Math.floor(d)})});
 const ops=[...new Set(G.map(x=>x.r.proj))].sort(),F=G.filter(x=>(!GO||x.r.proj==GO)&&(!GT||x.s.cat==GT)),C=V.filter(fin).filter(o=>!GO||o.proj==GO),
  pc=(a,b)=>b?Math.round(1000*a/b)/10+'%':'–',gi=F.filter(x=>x.s.cat=='Instalação').length,gm=F.length-gi,ci=C.filter(o=>o.cat=='Instalação').length,cm=C.length-ci,
  kc=(t,v,c)=>`<div class='kc' style='border-left-color:var(--${c})'><span>${t}</span><b>${v}</b></div>`,
  po=[...new Set([...C.map(o=>o.proj),...F.map(x=>x.r.proj)])].sort(),
  tc=Object.entries(GR(F,x=>x.s.tec)).map(([t,l])=>({t,n:l.length,op:l[0].s.proj,c:C.filter(o=>o.tec==t).length})).sort((a,b)=>b.n-a.n).slice(0,30);
 el.innerHTML=`<div class='bar' style='margin-top:0'><label>OP<select id='go'><option value=''>Todas</option>${ops.map(p=>`<option${p==GO?' selected':''}>${E(p)}</option>`).join('')}</select></label><label>Origem<select id='gt'><option value=''>Instalação e Mudança</option><option${GT=='Instalação'?' selected':''}>Instalação</option><option${GT=='Mudança'?' selected':''}>Mudança</option></select></label><button id='gx'>Baixar lista (CSV)</button><span class='mu'>Garantia = <b>Reparo</b> aberto em até <b>${GAR['Instalação']} dias</b> após a conclusão de uma <b>Instalação</b> ou <b>Mudança de Endereço</b> do mesmo cliente (Nº Cliente). Só enxerga instalações/mudanças presentes no Excel enviado.</span></div>`+
 `<div class='kp'>${kc('Garantias',F.length,'bad')+kc('Garantia de instalação',gi,'wa')+kc('Garantia de mudança',gm,'pu')+kc('% das instalações',pc(gi,ci),'wa')+kc('% das mudanças',pc(gm,cm),'pu')+kc('Reparos em aberto',F.filter(x=>!x.r.closed).length,'bad')}</div>`+
 '<h2>Por operação (OP)</h2>'+TB(['OP','Instalações concluídas','Garantia instalação','% instalação','Mudanças concluídas','Garantia mudança','% mudança','Total garantias'],po.map(p=>{const a=C.filter(o=>o.proj==p),f=F.filter(x=>x.r.proj==p),i1=a.filter(o=>o.cat=='Instalação').length,m1=a.length-i1,g1=f.filter(x=>x.s.cat=='Instalação').length,g2=f.length-g1;return[E(p),i1,g1,pc(g1,i1),m1,g2,pc(g2,m1),`<b>${f.length}</b>`]}))+
 '<h2>Perda de garantia por técnico instalador</h2>'+TB(['Técnico','OP','Concluídas (inst.+mud.)','Garantias','% garantia'],tc.map(x=>[E(x.t),E(x.op),x.c,`<b class='bd'>${x.n}</b>`,pc(x.n,x.c)]))+
 `<h2>Detalhe (${F.length}${F.length>300?' · mostrando 300':''})</h2>`+TB(['Situação','Cliente','Nº','Origem','OS origem','Concluída em','Técnico instalador','OS reparo','Reparo aberto em','Dias após','Status do reparo','OP','Cidade','Supervisor'],F.sort((a,b)=>b.r.ab-a.r.ab).slice(0,300).map(x=>[x.r.closed?'<span class="irrg">✔ Reparo finalizado</span>':'<span class="irrp">GARANTIA</span>',E(x.r.nome),x.r.cli,x.s.cat,x.s.os,fd(x.s.fim),E(x.s.tec),x.r.os,fd(x.r.ab),x.d,E(x.r.st),E(x.r.proj),E(x.r.cid),E(x.r.sup)]));
 $('#go').onchange=e=>{GO=e.target.value;gar(V,D)};$('#gt').onchange=e=>{GT=e.target.value;gar(V,D)};
 $('#gx').onclick=()=>{const q=s=>'"'+String(s??'').replace(/"/g,'""')+'"',r=[['OP','Cidade','Cliente','N Cliente','Origem','OS origem','Concluida em','Tecnico instalador','OS reparo','Reparo aberto em','Dias apos','Status reparo','Supervisor']];F.forEach(x=>r.push([x.r.proj,x.r.cid,x.r.nome,x.r.cli,x.s.cat,x.s.os,fd(x.s.fim),x.s.tec,x.r.os,fd(x.r.ab),x.d,x.r.st,x.r.sup]));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+r.map(x=>x.map(q).join(';')).join('\r\n')],{type:'text/csv'}));a.download='garantias.csv';a.click()}}
function grid(l,kf){const m=GR(l,kf),hs=[...Array(12)].map((_,i)=>i+8);
 return`<div class="sc"><table class="tg"><tr><th>Linha</th><th class="n">OS</th><th class="n">Venc.</th>${hs.map(h=>`<th>${p2(h)}h</th>`).join('')}</tr>`+Object.entries(m).sort((a,b)=>b[1].length-a[1].length).map(([k,v])=>`<tr><td>${E(k)}</td><td class="n">${v.length}</td><td class="n bd">${v.filter(o=>o.s=='venc').length||''}</td>${hs.map(h=>`<td>${v.filter(o=>Math.min(19,Math.max(8,(o.hd||o.ag).getHours()))==h).map(o=>`<i class="dot ${cls(o)} ${o.s=='venc'?'v':o.s=='hoje'?'hj':''}" title="${E(o.os+' · '+o.tipo+' · '+o.nome+' · '+o.st+' · '+fd(o.ag))}"></i>`).join('')}</td>`).join('')}</tr>`).join('')+'</table></div>'}
</script></body></html>
